// .fixtures.json is generated by global-setup.ts: run `npm run test:accessibility` to populate it.
const { projectId, itemId } = JSON.parse(
  readFileSync(
    join(dirname(fileURLToPath(import.meta.url)), ".fixtures.json"),
    "utf-8"
  )
) as { projectId: string; itemId: string };

// Two panels named after the header nav, each carrying its links, and the
// proposal statuses in order under them. Nothing on the page looks pressable
// without being a link (#393), and the panels stack at a phone width.
test("@smoke home page", async ({ page }) => {
  await page.goto("/");
  await expect(
    page.getByRole("link", { name: "Browse the catalog" })
  ).toHaveAttribute("href", "/projects");
  await expect(
    page.getByRole("link", { name: "Propose a project" })
  ).toHaveAttribute("href", "/projects/new");
  await expect(
    page.getByRole("link", { name: "See what you can borrow" })
  ).toHaveAttribute("href", "/inventory");
  await expect(page.getByRole("heading", { level: 3 })).toHaveText([
    "Draft",
    "Submitted",
    "Changes requested",
    "Approved",
    "Published",
  ]);
  await checkA11y(page);

  await page.setViewportSize({ width: 375, height: 812 });
  await expect(
    page.getByRole("link", { name: "Propose a project" })
  ).toBeVisible();
  await expect(
    page.getByRole("link", { name: "See what you can borrow" })
  ).toBeVisible();
  await expectNoHorizontalOverflow(page);
  await checkA11y(page);
});

test("@smoke sign-in page", async ({ page }) => {
  await page.goto("/sign-in");
  // The page-level privacy notice is a link in muted running text (#586).
  await expectUnderlinedAtRest(
    page.getByRole("link", { name: "privacy policy", exact: true })
  );
  await checkA11y(page);
});

/**
 * A save that fails announces, through `FieldError` (#411).
 *
 * Sign-in is the form a test can fail on demand without a fixture: a wrong
 * code, a real refusal from the server, and the message that comes back has to
 * reach a screen reader. Before `FieldError` carried `role="alert"`, all but
 * two of about forty of these paragraphs rendered silently, and the component
 * test can only prove the role is on the element; this proves a real failed
 * submit puts a real message inside it. The address needs no account: asking
 * for a code answers the same either way, and a wrong one is refused either
 * way.
 */
test("@smoke a failed sign-in announces its error", async ({ page }) => {
  await page.goto("/sign-in");
  await waitForHydration(page, "form");
  await expect(page.getByRole("alert")).toHaveCount(0);

  await page.getByLabel("Email", { exact: true }).fill("nobody@example.com");
  await page.getByRole("button", { name: "Email me a code" }).click();
  await page.getByLabel("Code", { exact: true }).fill("000000");
  await page.getByRole("button", { name: "Confirm code" }).click();

  const alert = page.getByRole("alert");
  await expect(alert).toBeVisible();
  await expect(alert).not.toBeEmpty();
  await expect(page).toHaveURL(/\/sign-in/);
  await checkA11y(page);
});

// The banner carries the office address as a link inside `role="alert"`, so
// the refusal and the one thing the reader can do about it are announced
// together. An unknown code lands on the fallback, which is what a new Better
// Auth error code would produce.
for (const code of ["user_info_is_missing", "not_a_known_code"]) {
  test(`@smoke sign-in page, ONID refusal ${code}`, async ({ page }) => {
    await page.goto(`/sign-in?error=${code}`);
    const alert = page.getByRole("alert");
    await expect(alert).toBeVisible();
    const link = alert.getByRole("link", { name: /@/ });
    await expect(link).toHaveAttribute("href", /^mailto:/);
    await expectUnderlinedAtRest(link);
    await link.focus();
    await expect(link).toBeFocused();
    await checkA11y(page);
  });
}

/**
 * The emailed code form, past its first step (#576).
 *
 * The page scan sees only the address step, because the later ones are behind
 * a real send. The code step therefore reaches no clean scan unless one drives
 * it, and it is the one most likely to go wrong: it is the only one-time-code
 * field in the app, drawn as six slots over one real input (#600), and a wrong
 * code marks every slot `aria-invalid`. Both states are scanned.
 *
 * The name step is scanned in the same test rather than its own, because each
 * test is a real send to one address in light and dark alike, and that address
 * has a per-recipient mail budget (ADR-0046). It carries the privacy notice's
 * link (#586). This suite has no mail log to read a code from, so the check is
 * answered the way the server answers a right code for an address with no
 * account; the form acts on the error code, which is all the stub has to match.
 */
test("@smoke sign-in page, the emailed code form", async ({ page }) => {
  await page.goto("/sign-in");
  await waitForHydration(page, "form");

  await page.getByLabel("Email", { exact: true }).fill("nobody@example.com");
  await page.getByRole("button", { name: "Email me a code" }).click();

  await expect(page.getByLabel("Code", { exact: true })).toBeVisible();
  await checkA11y(page);

  const check = "**/api/auth/email-otp/check-verification-otp";
  await page.route(check, (route) =>
    route.fulfill({
      status: 400,
      contentType: "application/json",
      body: JSON.stringify({ code: "INVALID_OTP", message: "Invalid OTP" }),
    })
  );
  await page.getByLabel("Code", { exact: true }).fill("000000");
  await page.getByRole("button", { name: "Confirm code" }).click();
  await expect(page.getByRole("alert")).toBeVisible();
  await checkA11y(page);
  await page.unroute(check);

  await page.route(check, (route) =>
    route.fulfill({
      status: 400,
      contentType: "application/json",
      body: JSON.stringify({
        code: "USER_NOT_FOUND",
        message: "User not found",
      }),
    })
  );
  await page.getByLabel("Code", { exact: true }).fill("123456");
  await page.getByRole("button", { name: "Confirm code" }).click();

  await expect(page.getByLabel("Your name", { exact: true })).toBeVisible();
  await expectUnderlinedAtRest(
    page
      .locator("form")
      .getByRole("link", { name: "privacy policy", exact: true })
  );
  await checkA11y(page);
});

